    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g


def _wall_cons(i):
    def jx(v): 
        g = np.zeros_like(v); g[3*i]=1; g[3*i+2]=-1; return g
    def jx2(v):
        g = np.zeros_like(v); g[3*i]=-1; g[3*i+2]=-1; return g
    def jy(v):
        g = np.zeros_like(v); g[3*i+1]=1; g[3*i+2]=-1; return g
    def jy2(v):
        g = np.zeros_like(v); g[3*i+1]=-1; g[3*i+2]=-1; return g
    return [
        {'type':'ineq','fun':lambda v,i=i: v[3*i]-v[3*i+2],'jac':jx},
        {'type':'ineq','fun':lambda v,i=i: 1.0-v[3*i]-v[3*i+2],'jac':jx2},
        {'type':'ineq','fun':lambda v,i=i: v[3*i+1]-v[3*i+2],'jac':jy},
        {'type':'ineq','fun':lambda v,i=i: 1.0-v[3*i+1]-v[3*i+2],'jac':jy2},
    ]


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.extend(_wall_cons(i))
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.extend([(0.0, 1.0), (0.0, 1.0), (1e-6, 0.5)])
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3 * i + 2] = min(max(v0[3 * i + 2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    candidates = []

    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    bestA = _slsqp(arrA, cons, 1500)
    if np.sum(bestA[:, 2]) < np.sum(arrA[:, 2]):
        bestA = arrA
    candidates.append(bestA)

    # Multiple FPS seeds with LP radii
    for seed in range(3):
        if time.process_time() - t0 > 0.55 * budget_seconds:
            break
        centers = _fps_centers(n, seed=seed)
        radii = _lp_radii(centers)
        arrB = _feasible(np.column_stack([centers, radii]))
        candB = _slsqp(arrB, cons, 2000)
        if np.sum(candB[:, 2]) < np.sum(arrB[:, 2]):
            candB = arrB
        candidates.append(candB)

    best = max(candidates, key=lambda a: np.sum(a[:, 2]))

    # Perturbation + re-optimization loop
    rng = np.random.default_rng(7)
    while time.process_time() - t0 < 0.88 * budget_seconds:
        arr = best.copy()
        scale_xy = rng.uniform(0.005, 0.02)
        arr[:, 0:2] += rng.normal(0.0, scale_xy, size=(n, 2))
        arr[:, 2] += rng.normal(0.0, 0.004, size=n)
        arr[:, 2] = np.clip(arr[:, 2], 1e-6, 0.5)
        arr = _feasible(arr)
        cand = _slsqp(arr, cons, 1500)
        cand = _feasible(cand)
        if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
            best = cand.copy()

    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-8, 1e-9)
    out = _feasible(out)
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out = _feasible(out)
    return out

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
    return np.array([[x, y, 0.09] for x, y in pts], dtype=float)


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            if arr[i, 0] - r < 0:
                arr[i, 2] = arr[i, 0]
            if 1 - arr[i, 0] - r < 0:
                arr[i, 2] = 1 - arr[i, 0]
            if arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], arr[i, 1])
            if 1 - arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []; b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    try:
        res = linprog(c, A_ub=np.array(A), b_ub=np.array(b),
                      bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x2(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3 * i + 2] = min(max(v0[3 * i + 2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        if base.shape != (n, 3):
            base = _initial()
    else:
        base = _initial()
    base = _feasible(base)

    best = base.copy()
    best_score = np.sum(best[:, 2])

    def try_candidate(arr0, maxiter=600):
        nonlocal best, best_score
        arr = _slsqp(arr0, cons, maxiter, 1e-12)
        arr = _feasible(arr)
        s = np.sum(arr[:, 2])
        if s > best_score:
            best = arr
            best_score = s
        return arr

    # Baseline polish of start
    try_candidate(base, 1000)

    rng = np.random.default_rng(424242)
    it = 0
    while time.process_time() - t0 < 0.88 * budget_seconds:
        # Mix of scales: most small, occasionally large
        if it % 4 == 0:
            sigma_xy = 0.030
        elif it % 4 == 1:
            sigma_xy = 0.015
        else:
            sigma_xy = 0.006
        arr = best.copy()
        arr[:, 0:2] += rng.normal(0.0, sigma_xy, size=(n, 2))
        arr[:, 2] += rng.normal(0.0, 0.35 * sigma_xy, size=n)
        arr[:, 2] = np.clip(arr[:, 2], 1e-6, 0.5)
        arr = _feasible(arr)

        # Alternate: full SLSQP vs LP-then-SLSQP
        if it % 2 == 0:
            arr = try_candidate(arr, 400)
            centers = arr[:, :2].copy()
            r = _lp_radii(centers)
            arr2 = _feasible(np.column_stack([centers, r]))
            try_candidate(arr2, 300)
        else:
            arr = try_candidate(arr, 500)

        it += 1

    # Final deep polish
    if time.process_time() - t0 < 0.95 * budget_seconds:
        arr = _slsqp(best, cons, 1200, 1e-13)
        arr = _feasible(arr)
        if np.sum(arr[:, 2]) > best_score:
            best = arr
            best_score = np.sum(arr[:, 2])

    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out = _feasible(out)
    out[:, 2] = np.maximum(out[:, 2] - 1e-10, 1e-9)
    out = _feasible(out)
    return out


def _jac_wall_x(v, i):
    g = np.zeros_like(v); g[3 * i] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_x2(v, i):
    g = np.zeros_like(v); g[3 * i] = -1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y2(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0; return g

def _pair(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2

def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-13
                    arr[j, 2] -= excess * 0.5 + 1e-13
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            r = min(r, arr[i, 0], 1 - arr[i, 0], arr[i, 1], 1 - arr[i, 1])
            arr[i, 2] = max(r, 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    A = np.array(A); b = np.array(b)
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _make_cons(n):
    def cf(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        out = []
        out.append(x - r)
        out.append(1.0 - x - r)
        out.append(y - r)
        out.append(1.0 - y - r)
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        dr = r[:, None] + r[None, :]
        D = dx * dx + dy * dy - dr * dr
        iu = np.triu_indices(n, 1)
        out.append(D[iu])
        return np.concatenate(out)

    def cj(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        rows = []
        for k in range(4):
            G = np.zeros((n, 3 * n))
            for i in range(n):
                if k == 0:
                    G[i, 3 * i] = 1.0; G[i, 3 * i + 2] = -1.0
                elif k == 1:
                    G[i, 3 * i] = -1.0; G[i, 3 * i + 2] = -1.0
                elif k == 2:
                    G[i, 3 * i + 1] = 1.0; G[i, 3 * i + 2] = -1.0
                else:
                    G[i, 3 * i + 1] = -1.0; G[i, 3 * i + 2] = -1.0
            rows.append(G)
        iu = np.triu_indices(n, 1)
        ii, jj = iu
        m = len(ii)
        G = np.zeros((m, 3 * n))
        dx = x[ii] - x[jj]; dy = y[ii] - y[jj]; s = r[ii] + r[jj]
        for t in range(m):
            i = ii[t]; j = jj[t]
            G[t, 3 * i] = 2 * dx[t]
            G[t, 3 * i + 1] = 2 * dy[t]
            G[t, 3 * i + 2] = -2 * s[t]
            G[t, 3 * j] = -2 * dx[t]
            G[t, 3 * j + 1] = -2 * dy[t]
            G[t, 3 * j + 2] = -2 * s[t]
        rows.append(G)
        return np.vstack(rows)

    cons = [{'type': 'ineq', 'fun': cf, 'jac': cj}]
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-7, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3 * i + 2] = min(max(v0[3 * i + 2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _detect_active(arr, tol=1e-6):
    n = arr.shape[0]
    walls = []
    for i in range(n):
        x, y, r = arr[i]
        if x - r < tol: walls.append((i, 0))
        if 1.0 - x - r < tol: walls.append((i, 1))
        if y - r < tol: walls.append((i, 2))
        if 1.0 - y - r < tol: walls.append((i, 3))
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(arr[i, 0] - arr[j, 0], arr[i, 1] - arr[j, 1])
            if d - (arr[i, 2] + arr[j, 2]) < tol:
                pairs.append((i, j))
    return walls, pairs


def _make_eq_cons(n, walls, pairs):
    def ef(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        out = []
        for (i, k) in walls:
            if k == 0: out.append(x[i] - r[i])
            elif k == 1: out.append(1.0 - x[i] - r[i])
            elif k == 2: out.append(y[i] - r[i])
            else: out.append(1.0 - y[i] - r[i])
        for (i, j) in pairs:
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            out.append(d - (r[i] + r[j]))
        if not out:
            return np.zeros(0)
        return np.array(out)

    def ej(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        m = len(walls) + len(pairs)
        G = np.zeros((m, 3 * n))
        row = 0
        for (i, k) in walls:
            if k == 0:
                G[row, 3 * i] = 1.0; G[row, 3 * i + 2] = -1.0
            elif k == 1:
                G[row, 3 * i] = -1.0; G[row, 3 * i + 2] = -1.0
            elif k == 2:
                G[row, 3 * i + 1] = 1.0; G[row, 3 * i + 2] = -1.0
            else:
                G[row, 3 * i + 1] = -1.0; G[row, 3 * i + 2] = -1.0
            row += 1
        for (i, j) in pairs:
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = np.hypot(dx, dy)
            if d < 1e-12:
                d = 1e-12
            ux = dx / d; uy = dy / d
            G[row, 3 * i] = ux; G[row, 3 * i + 1] = uy; G[row, 3 * i + 2] = -1.0
            G[row, 3 * j] = -ux; G[row, 3 * j + 1] = -uy; G[row, 3 * j + 2] = -1.0
            row += 1
        return G

    return {'type': 'eq', 'fun': ef, 'jac': ej}


def _slsqp_eq(arr, cons, eqcons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
