        if arrA.shape != (n, 3):
            arrA = None
        else:
            arrA = _feasible(arrA)
            candidates.append(arrA)

    if not candidates:
        centers = []
        for k, c in enumerate([5, 4, 5, 4, 5, 3]):
            s = 1.0 / 5.0
            rh = s * np.sqrt(3) / 2
            off = (s / 2) if k % 2 else 0.0
            for i in range(c):
                centers.append(((i + 0.5) * s + off, (k + 0.5) * rh))
        centers = np.array(centers)
        centers[:, 0] = np.clip(centers[:, 0], 0.01, 0.99)
        centers[:, 1] = np.clip(centers[:, 1], 0.01, 0.99)
        r = _lp_radii(centers)
        candidates.append(_feasible(np.column_stack([centers, r])))

    best = None
    bestscore = -1.0
    for arr in candidates:
        if time.process_time() - t0 > budget_seconds * 0.35:
            break
        opt = _slsqp(arr, cons, 2000, 1e-13)
        if np.sum(opt[:, 2]) < np.sum(arr[:, 2]):
            opt = arr
        sc = float(np.sum(opt[:, 2]))
        if sc > bestscore:
            bestscore = sc; best = opt

    rng = np.random.default_rng(987654321)
    it = 0
    while time.process_time() - t0 < 0.75 * budget_seconds:
        arr = best.copy()
        arr[:, 0:2] += rng.normal(0.0, 0.008, size=(n, 2))
        arr[:, 2] += rng.normal(0.0, 0.004, size=n)
        arr[:, 2] = np.clip(arr[:, 2], 1e-6, 0.5)
        arr = _feasible(arr)
        arr = _slsqp(arr, cons, 500, 1e-12)
        sc = float(np.sum(arr[:, 2]))
        if sc > bestscore:
            bestscore = sc; best = arr
        it += 1

    # Active-set polish
    polish_best = best.copy()
    polish_score = bestscore
    for _round in range(3):
        if time.process_time() - t0 > 0.93 * budget_seconds:
            break
        walls, pairs = _detect_active(polish_best, tol=1e-6)
        if not walls and not pairs:
            break
        eqcons = _make_eq_cons(n, walls, pairs)
        cand = _slsqp_eq(polish_best, cons, eqcons, 1000, 1e-13)
        cand = _feasible(cand)
        # recompute LP radii at fixed centers
        centers = cand[:, :2].copy()
        try:
            rlp = _lp_radii(centers)
            cand2 = np.column_stack([centers, rlp])
            cand2 = _feasible(cand2)
            cand2 = _slsqp(cand2, cons, 1000, 1e-13)
            cand2 = _feasible(cand2)
            if np.sum(cand2[:, 2]) > np.sum(cand[:, 2]):
                cand = cand2
        except Exception:
            pass
        sc = float(np.sum(cand[:, 2]))
        if sc > polish_score + 1e-12:
            polish_score = sc
            polish_best = cand
        else:
            break

    if polish_score > bestscore:
        best = polish_best
        bestscore = polish_score

    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out = _feasible(out)
    out[:, 2] = np.maximum(out[:, 2] - 1e-10, 1e-9)
    for _ in range(3):
        out[:, 2] *= (1.0 - 1e-12)
    out = _feasible(out)
    print("final=%.9f iters=%d" % (float(np.sum(out[:, 2])), it))
    return out

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
    r0 = 0.09
    arr = np.array([[x, y, r0] for x, y in pts], dtype=float)
    return arr


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    for i in range(arr.shape[0]):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    n = arr.shape[0]
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            if arr[i, 0] - r < 0:
                arr[i, 2] = arr[i, 0]
            if 1 - arr[i, 0] - r < 0:
                arr[i, 2] = 1 - arr[i, 0]
            if arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], arr[i, 1])
            if 1 - arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A.append(row)
            b.append(d)
    A = np.array(A)
    b = np.array(b)
    bounds = [(0.0, None)] * n
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x2(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3 * i + 2] = min(max(v0[3 * i + 2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _ruin_recreate(state, best, cons, rng, n):
    k = int(rng.integers(3, 6))
    if rng.random() < 0.5:
        order = np.argsort(state[:, 2])
        pool = order[:max(k, n // 2)]
        idx = rng.choice(pool, size=k, replace=False)
    else:
        idx = rng.choice(n, size=k, replace=False)
    arr = state.copy()
    survivors = np.setdiff1d(np.arange(n), idx)
    for i in idx:
        for _ in range(20):
            cx = rng.uniform(0.05, 0.95)
            cy = rng.uniform(0.05, 0.95)
            if survivors.size == 0:
                break
            d = np.hypot(arr[survivors, 0] - cx, arr[survivors, 1] - cy)
            if np.all(d >= 0.02):
                break
        arr[i, 0] = cx
        arr[i, 1] = cy
        arr[i, 2] = 0.01
    centers = arr[:, :2].copy()
    r = _lp_radii(centers)
    arr = np.column_stack([centers, r])
    arr = _feasible(arr)
    arr = _slsqp(arr, cons, 300, 1e-12)
    return arr


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    bestA = _slsqp(arrA, cons, 1000)
    if _obj(bestA.reshape(-1)) > _obj(arrA.reshape(-1)):
        bestA = arrA
    if time.process_time() - t0 < budget_seconds * 0.5:
        cand = _slsqp(bestA, cons, 500, 1e-13)
        if _obj(cand.reshape(-1)) < _obj(bestA.reshape(-1)):
            bestA = cand

    best = bestA
    current = bestA.copy()

    rng = np.random.default_rng(12345)
    it = 0
    while time.process_time() - t0 < 0.85 * budget_seconds:
        new = _ruin_recreate(current, best, cons, rng, n)
        s_new = np.sum(new[:, 2])
        s_best = np.sum(best[:, 2])
        s_cur = np.sum(current[:, 2])
        if s_new > s_best:
            best = new.copy()
        if s_new > s_cur:
            current = new.copy()
        else:
            if rng.random() < 0.9:
                current = best.copy()
            else:
                current = new.copy()
        it += 1

    if time.process_time() - t0 < 0.95 * budget_seconds:
        cand = _slsqp(best, cons, 800, 1e-13)
        if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
            best = cand

    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out = _feasible(out)
    out[:, 2] = np.maximum(out[:, 2] - 1e-10, 1e-9)
    out = _feasible(out)
    return out


def _jac_wall_x(v, i):
    g = np.zeros_like(v); g[3 * i] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_x2(v, i):
    g = np.zeros_like(v); g[3 * i] = -1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y2(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0; return g

def _pair(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2

def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
    r0 = 0.09
    return np.array([[x, y, r0] for x, y in pts], dtype=float)


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            if arr[i, 0] - r < 0:
                arr[i, 2] = arr[i, 0]
            if 1 - arr[i, 0] - r < 0:
                arr[i, 2] = 1 - arr[i, 0]
            if arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], arr[i, 1])
            if 1 - arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    A = np.array(A); b = np.array(b)
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i, 1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i, -1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i+1, 1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i+1, -1.0))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq', 'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _jw(v, idx, sign):
    g = np.zeros_like(v); g[idx] = sign; g[idx + (2 if idx % 3 == 0 or idx % 3 == 1 else 0)] = -1.0
    # fix: wall constraint r coeff is -1 on the radius component
    g = np.zeros_like(v)
    g[idx] = sign
    base = (idx // 3) * 3 + 2
    g[base] = -1.0
    return g


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v); g.reshape(-1, 3)[:, 2] = -1.0; return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP', bounds=bounds,
                       constraints=cons, options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _pair(v, i, j):
    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
    s = v[3*i+2] + v[3*j+2]
    return dx*dx + dy*dy - s*s


def _pair_jac(v, i, j):
    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
    s = v[3*i+2] + v[3*j+2]
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _score(arr):
    return float(np.sum(arr[:, 2]))


def _finalize(arr):
    """Return a strictly feasible array with safety margin on all constraints."""
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    # shrink radii to be safe
    arr[:, 2] = np.maximum(arr[:, 2] - 1e-9, 1e-9)
    # clamp centers so walls hold (with margin)
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r + 1e-12), 1.0 - r - 1e-12)
        arr[i, 1] = min(max(arr[i, 1], r + 1e-12), 1.0 - r - 1e-12)
    # resolve pair overlaps by shrinking radii
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]; dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s + 1e-12:
                    excess = s + 1e-12 - d
                    arr[i, 2] -= excess * 0.5 + 1e-13
                    arr[j, 2] -= excess * 0.5 + 1e-13
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            arr[i, 2] = min(r, arr[i, 0] - 1e-12, 1.0 - arr[i, 0] - 1e-12,
                            arr[i, 1] - 1e-12, 1.0 - arr[i, 1] - 1e-12)
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    # Candidate A: refine start
    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    best = arrA.copy()
    cand = _slsqp(arrA, cons, 800, 1e-13)
    if _score(cand) > _score(best):
        best = cand

    # Candidate B: LP-polish centers of start (keeps geometry, maximizes radii)
    if start is not None and time.process_time() - t0 < 0.5 * budget_seconds:
        centers = best[:, :2].copy()
        r = _lp_radii(centers)
        arrB = _feasible(np.column_stack([centers, r]))
        candB = _slsqp(arrB, cons, 600, 1e-13)
        if _score(candB) > _score(best):
            best = candB

    # Perturbation loop with adaptive sigma, accepting improvements
    rng = np.random.default_rng(987654321)
    it = 0
    limit = 0.92 * budget_seconds
    while time.process_time() - t0 < limit:
        sigma_xy = max(0.0015, 0.012 * (0.94 ** it))
        sigma_r = 0.5 * sigma_xy
        arr = best.copy()
        # perturb a random subset of circles
        k = rng.integers(2, n + 1)
        idx = rng.choice(n, size=k, replace=False)
        arr[idx, 0] += rng.normal(0.0, sigma_xy, size=k)
        arr[idx, 1] += rng.normal(0.0, sigma_xy, size=k)
        arr[idx, 2] = np.clip(arr[idx, 2] + rng.normal(0.0, sigma_r, size=k), 1e-6, 0.5)
        arr = _feasible(arr)
        arr = _slsqp(arr, cons, 250, 1e-12)

        centers = arr[:, :2].copy()
        r = _lp_radii(centers)
        arr2 = _feasible(np.column_stack([centers, r]))
        arr2 = _slsqp(arr2, cons, 200, 1e-12)

        if _score(arr2) > _score(best):
            best = arr2
        elif _score(arr) > _score(best):
            best = arr
        it += 1

    # Final LP-radius polish on best centers
    if time.process_time() - t0 < 0.97 * budget_seconds:
        centers = best[:, :2].copy()
        r = _lp_radii(centers)
        arrF = _feasible(np.column_stack([centers, r]))
        arrF = _slsqp(arrF, cons, 400, 1e-13)
        if _score(arrF) > _score(best):
            best = arrF

    return _finalize(best)

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
    r0 = 0.09
    arr = np.array([[x, y, r0] for x, y in pts], dtype=float)
    return arr


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    for i in range(arr.shape[0]):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    n = arr.shape[0]
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            if arr[i, 0] - r < 0:
                arr[i, 2] = arr[i, 0]
            if 1 - arr[i, 0] - r < 0:
                arr[i, 2] = 1 - arr[i, 0]
            if arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], arr[i, 1])
            if 1 - arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A.append(row)
            b.append(d)
    A = np.array(A)
    b = np.array(b)
    bounds = [(0.0, None)] * n
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _fps_centers_random(n, rng, grid=60):
    xs = (np.arange(grid) + 0.5) / grid
    cand = np.array([[x, y] for y in xs for x in xs])
    first = rng.uniform(0.05, 0.95, size=2)
    idx = np.argmin(np.hypot(cand[:, 0] - first[0], cand[:, 1] - first[1]))
    chosen = [cand[idx]]
    chosen = np.array(chosen)
    for _ in range(n - 1):
        d = np.min(np.hypot(cand[:, 0:1] - chosen[:, 0][None, :],
                            cand[:, 1:2] - chosen[:, 1][None, :]), axis=1)
        idx = np.argmax(d)
        chosen = np.vstack([chosen, cand[idx]])
    return chosen[:n]


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x2(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3 * i + 2] = min(max(v0[3 * i + 2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    # Candidate A: from start (or initial)
    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    bestA = _slsqp(arrA, cons, 1000)
    if _obj(bestA.reshape(-1)) > _obj(arrA.reshape(-1)):
        bestA = arrA
    if time.process_time() - t0 < budget_seconds * 0.25:
        cand = _slsqp(bestA, cons, 500, 1e-13)
        if _obj(cand.reshape(-1)) < _obj(bestA.reshape(-1)):
            bestA = cand

    best = bestA.copy()
    best_score = np.sum(best[:, 2])

    # Candidate B: 50 randomized FPS starts
    rng = np.random.default_rng(202411)
    results = []
    n_starts = 50
    for k in range(n_starts):
        if time.process_time() - t0 > 0.70 * budget_seconds:
            break
        centers = _fps_centers_random(n, rng, grid=60)
        radii = _lp_radii(centers)
        arrB = np.column_stack([centers, radii])
        arrB = _feasible(arrB)
        candB = _slsqp(arrB, cons, 500, 1e-12)
        if _obj(candB.reshape(-1)) > _obj(arrB.reshape(-1)):
            candB = arrB
        sc = np.sum(candB[:, 2])
        results.append((sc, candB))
        if sc > best_score:
            best_score = sc
            best = candB.copy()

    # Rerun top 5 with 2000 iters using remaining time
    results.sort(key=lambda t: -t[0])
    for sc, arr in results[:5]:
        if time.process_time() - t0 > 0.93 * budget_seconds:
            break
        cand = _slsqp(arr, cons, 2000, 1e-13)
        if _obj(cand.reshape(-1)) > _obj(arr.reshape(-1)):
            cand = arr
        sc2 = np.sum(cand[:, 2])
        if sc2 > best_score:
            best_score = sc2
            best = cand.copy()

    # Exact per-constraint float-level polish
    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    for _ in range(100):
        violated = False
        for i in range(n):
            x, y = centers[i, 0], centers[i, 1]
            for dist in (x, 1.0 - x, y, 1.0 - y):
                if r[i] > dist:
                    r[i] -= (r[i] - dist) + 1e-15
                    violated = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr
                    r[j] -= corr
                    violated = True
        if not violated:
            break
    r = np.maximum(r, 1e-9)
    return np.column_stack([centers, r])


def _jac_wall_x(v, i):
    g = np.zeros_like(v); g[3 * i] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_x2(v, i):
    g = np.zeros_like(v); g[3 * i] = -1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y2(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0; return g

def _pair(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2

def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g

