def _pair(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g


def _build_cons(n):
    cons = []
    for i in range(n):
        def jx(v, i=i):
            g = np.zeros_like(v); g[3*i]=1; g[3*i+2]=-1; return g
        def jx2(v, i=i):
            g = np.zeros_like(v); g[3*i]=-1; g[3*i+2]=-1; return g
        def jy(v, i=i):
            g = np.zeros_like(v); g[3*i+1]=1; g[3*i+2]=-1; return g
        def jy2(v, i=i):
            g = np.zeros_like(v); g[3*i+1]=-1; g[3*i+2]=-1; return g
        cons.append({'type':'ineq','fun':(lambda v,i=i: v[3*i]-v[3*i+2]),'jac':jx})
        cons.append({'type':'ineq','fun':(lambda v,i=i: 1.0-v[3*i]-v[3*i+2]),'jac':jx2})
        cons.append({'type':'ineq','fun':(lambda v,i=i: v[3*i+1]-v[3*i+2]),'jac':jy})
        cons.append({'type':'ineq','fun':(lambda v,i=i: 1.0-v[3*i+1]-v[3*i+2]),'jac':jy2})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.extend([(0.0, 1.0), (0.0, 1.0), (1e-6, 0.5)])
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3 * i + 2] = min(max(v0[3 * i + 2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _reinsert(arr, cons, k=3, grid=60, maxiter=600):
    n = arr.shape[0]
    order = np.argsort(arr[:, 2])
    del_idx = order[:k]
    keep_mask = np.ones(n, dtype=bool)
    keep_mask[del_idx] = False
    kept = arr[keep_mask]
    xs = (np.arange(grid) + 0.5) / grid
    cand = np.array([[x, y] for y in xs for x in xs])
    reinserted = []
    for _ in range(k):
        pts = kept[:, :2]
        if reinserted:
            pts = np.vstack([pts, np.array(reinserted)])
        d = np.min(np.hypot(cand[:, 0:1] - pts[:, 0][None, :],
                            cand[:, 1:2] - pts[:, 1][None, :]), axis=1)
        idx = np.argmax(d)
        reinserted.append(cand[idx])
    new_centers = np.vstack([kept[:, :2], np.array(reinserted)])
    r = _lp_radii(new_centers)
    arr2 = np.column_stack([new_centers, r])
    arr2 = _feasible(arr2)
    arr2 = _slsqp(arr2, cons, maxiter, 1e-12)
    return arr2


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    best = _slsqp(arrA, cons, 800)
    if np.sum(best[:, 2]) < np.sum(arrA[:, 2]):
        best = arrA

    # Reinsertion loop: swap out smallest circles, reinsert into largest gaps
    stall = 0
    while time.process_time() - t0 < 0.85 * budget_seconds:
        k = 2 + (stall % 3)
        cand = _reinsert(best, cons, k=k, grid=50, maxiter=500)
        if np.sum(cand[:, 2]) > np.sum(best[:, 2]) + 1e-11:
            best = cand.copy()
            stall = 0
        else:
            stall += 1

    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-8, 1e-9)
    out = _feasible(out)
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out = _feasible(out)
    return out

