    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3 * i] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_x2(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3 * i + 1] - v[3 * i + 2]),
                     'jac': (lambda v, i=i: _jac_wall_y2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq', 'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])

def _obj_grad(v):
    g = np.zeros_like(v); g.reshape(-1, 3)[:, 2] = -1.0; return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3 * i + 2] = min(max(v0[3 * i + 2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _polish(centers, r):
    n = centers.shape[0]
    r = r.copy()
    for _ in range(300):
        violated = False
        for i in range(n):
            x, y = centers[i, 0], centers[i, 1]
            for dist in (x, 1.0 - x, y, 1.0 - y):
                if r[i] > dist:
                    r[i] -= (r[i] - dist) + 1e-15
                    violated = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr; r[j] -= corr
                    violated = True
        if not violated:
            break
    return np.maximum(r, 1e-9)


def _score(arr):
    return float(np.sum(arr[:, 2]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    # Candidate A: from start
    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    bestA = _slsqp(arrA, cons, 800, 1e-13)
    if _score(bestA) < _score(arrA):
        bestA = arrA

    best = bestA.copy()
    best_score = _score(best)

    # Candidate B: randomized FPS starts
    rng = np.random.default_rng(777)
    results = []
    n_starts = 40
    for k in range(n_starts):
        if time.process_time() - t0 > 0.55 * budget_seconds:
            break
        centers = _fps_centers_random(n, rng, grid=60)
        radii = _lp_radii(centers)
        arrB = _feasible(np.column_stack([centers, radii]))
        candB = _slsqp(arrB, cons, 400, 1e-12)
        if _score(candB) < _score(arrB):
            candB = arrB
        sc = _score(candB)
        results.append((sc, candB))
        if sc > best_score:
            best_score = sc; best = candB.copy()

    # Rerun top candidates with more iterations
    results.sort(key=lambda t: -t[0])
    for sc, arr in results[:6]:
        if time.process_time() - t0 > 0.80 * budget_seconds:
            break
        cand = _slsqp(arr, cons, 1500, 1e-13)
        if _score(cand) < _score(arr):
            cand = arr
        if _score(cand) > best_score:
            best_score = _score(cand); best = cand.copy()

    # Perturb-and-reoptimize the best
    it = 0
    while time.process_time() - t0 < 0.92 * budget_seconds:
        arr = best.copy()
        sigma = 0.008 if it % 2 == 0 else 0.004
        arr[:, 0:2] += rng.normal(0.0, sigma, size=(n, 2))
        arr = _feasible(arr)
        arr = _slsqp(arr, cons, 300, 1e-12)
        if _score(arr) > best_score:
            best_score = _score(arr); best = arr.copy()
        it += 1
        if it > 30:
            break

    # Final LP radii at fixed centers of best, then polish
    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    return np.column_stack([centers, r])

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
