def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    for i in range(arr.shape[0]):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    n = arr.shape[0]
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            if arr[i, 0] - r < 0:
                arr[i, 2] = arr[i, 0]
            if 1 - arr[i, 0] - r < 0:
                arr[i, 2] = 1 - arr[i, 0]
            if arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], arr[i, 1])
            if 1 - arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
