                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr
                    r[j] -= corr
                    violated = True
        if not violated:
            break
    return r


def _max_radius_at(center, others):
    """Max feasible radius for a circle at `center` given other circles (x,y,r)."""
    x, y = center
    rmax = min(x, 1.0 - x, y, 1.0 - y)
    if rmax <= 0:
        return 0.0
    for (ox, oy, orr) in others:
        d = np.hypot(x - ox, y - oy) - orr
        if d < rmax:
            rmax = d
    return max(rmax, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    best = _slsqp(arrA, cons, 1000)
    if _obj(best.reshape(-1)) > _obj(arrA.reshape(-1)):
        best = arrA

    # Delete-and-reinsert loop
    rng = np.random.default_rng(98765)
    cons25 = _build_cons(n - 1)
    it = 0
    accepted = 0
    while time.process_time() - t0 < 0.90 * budget_seconds:
        # Pick circle: alternate smallest-radius and random
        if it % 2 == 0:
            k = int(np.argmin(best[:, 2]))
        else:
            k = int(rng.integers(0, n))
        reduced = np.delete(best, k, axis=0)
        reduced = _feasible(reduced)
        reduced = _slsqp(reduced, cons25, 400, 1e-12)

        # Try random candidate centers for the removed circle
        others = reduced
        best_r = -1.0
        best_c = None
        n_cand = 200
        for _ in range(n_cand):
            cx = rng.uniform(0.0, 1.0)
            cy = rng.uniform(0.0, 1.0)
            rr = _max_radius_at((cx, cy), others)
            if rr > best_r:
                best_r = rr
                best_c = (cx, cy)
        if best_c is None or best_r <= 1e-9:
            it += 1
            continue

        new_arr = np.vstack([reduced, np.array([[best_c[0], best_c[1], best_r]])])
        new_arr = _feasible(new_arr)
        new_arr = _slsqp(new_arr, cons, 800, 1e-12)

        if np.sum(new_arr[:, 2]) > np.sum(best[:, 2]) + 1e-12:
            best = new_arr
            accepted += 1
        it += 1

    # Final polish
    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    r = np.maximum(r, 1e-9)
    return np.column_stack([centers, r])


def _jac_wall_x(v, i):
    g = np.zeros_like(v); g[3 * i] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_x2(v, i):
    g = np.zeros_like(v); g[3 * i] = -1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y2(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0; return g

def _pair(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2

def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g

