        idx = int(np.argmax(d))
        chosen.append(idx)
        nd = np.hypot(pts[:, 0] - pts[idx, 0], pts[:, 1] - pts[idx, 1])
        d = np.minimum(d, nd)
    return pts[chosen]


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    bestA = _slsqp(arrA, cons, 800)
    if np.sum(bestA[:, 2]) < np.sum(arrA[:, 2]):
        bestA = arrA
    best = bestA

    # Multi-start from lattice seeds when time allows
    if time.process_time() - t0 < 0.35 * budget_seconds:
        for centers in _lattice_seeds(n):
            if time.process_time() - t0 >= 0.55 * budget_seconds:
                break
            radii = _lp_radii(centers)
            arr = _feasible(np.column_stack([centers, radii]))
            cand = _slsqp(arr, cons, 600)
            if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
                best = cand

    # Active-set polish
    if time.process_time() - t0 < 0.85 * budget_seconds:
        cons_act = _build_cons(n, active_tol=1e-6, arr0=best)
        cand = _slsqp(best, cons_act, 1500, 1e-14)
        if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
            best = cand

    # Perturbation loop
    rng = np.random.default_rng(987654321)
    it = 0
    while time.process_time() - t0 < 0.90 * budget_seconds:
        arr = best.copy()
        scale = 0.008 if it % 3 else 0.02
        arr[:, 0:2] += rng.normal(0.0, scale, size=(n, 2))
        arr[:, 2] += rng.normal(0.0, scale * 0.5, size=n)
        arr[:, 2] = np.clip(arr[:, 2], 1e-6, 0.5)
        arr = _feasible(arr)
        arr = _slsqp(arr, cons, 350, 1e-12)
        centers = arr[:, :2].copy()
        r = _lp_radii(centers)
        arr2 = _feasible(np.column_stack([centers, r]))
        arr2 = _slsqp(arr2, cons, 250, 1e-12)
        if np.sum(arr2[:, 2]) > np.sum(best[:, 2]):
            best = arr2
        it += 1

    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    return np.column_stack([centers, r])


def _jw(v, i, kind):
    g = np.zeros_like(v)
    if kind == 0:
        g[3 * i] = 1.0
    elif kind == 1:
        g[3 * i] = -1.0
    elif kind == 2:
        g[3 * i + 1] = 1.0
    else:
        g[3 * i + 1] = -1.0
    g[3 * i + 2] = -1.0
    return g


def _pair(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _unpack(v):
    return v.reshape(-1, 3)


def _obj(v):
    return -np.sum(_unpack(v)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    _unpack(g)[:, 2] = -1.0
    return g


def _pair_cons(v, i, j):
    a = _unpack(v)
    dx = a[i, 0] - a[j, 0]
    dy = a[i, 1] - a[j, 1]
    s = a[i, 2] + a[j, 2]
    return dx * dx + dy * dy - s * s


def _pair_grad(v, i, j):
    a = _unpack(v)
    dx = a[i, 0] - a[j, 0]
    dy = a[i, 1] - a[j, 1]
    s = a[i, 2] + a[j, 2]
    g = np.zeros_like(v)
    b = g.reshape(-1, 3)
    b[i, 0] = 2 * dx; b[i, 1] = 2 * dy; b[i, 2] = -2 * s
    b[j, 0] = -2 * dx; b[j, 1] = -2 * dy; b[j, 2] = -2 * s
    return g


def _wall_cons(v, i, k, sign):
    a = _unpack(v)
    if k == 0:
        return sign * (a[i, 0] - a[i, 2]) if sign > 0 else (1.0 - a[i, 0] - a[i, 2])
    else:
        return sign * (a[i, 1] - a[i, 2]) if sign > 0 else (1.0 - a[i, 1] - a[i, 2])


def _wall_grad(v, i, k, sign):
    g = np.zeros_like(v)
    b = g.reshape(-1, 3)
    if k == 0:
        b[i, 0] = sign; b[i, 2] = -sign
    else:
        b[i, 1] = sign; b[i, 2] = -sign
    return g


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: _unpack(v)[i, 0] - _unpack(v)[i, 2]),
                     'jac': (lambda v, i=i: _wall_grad(v, i, 0, 1.0))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - _unpack(v)[i, 0] - _unpack(v)[i, 2]),
                     'jac': (lambda v, i=i: _wall_grad(v, i, 0, -1.0))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: _unpack(v)[i, 1] - _unpack(v)[i, 2]),
                     'jac': (lambda v, i=i: _wall_grad(v, i, 1, 1.0))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - _unpack(v)[i, 1] - _unpack(v)[i, 2]),
                     'jac': (lambda v, i=i: _wall_grad(v, i, 1, -1.0))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair_cons(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_grad(v, i, j))})
    return cons


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(80):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s - 1e-15:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-15
                    arr[j, 2] -= excess * 0.5 + 1e-15
                    changed = True
        for i in range(n):
            r = min(arr[i, 2], arr[i, 0], 1 - arr[i, 0], arr[i, 1], 1 - arr[i, 1])
            if r < arr[i, 2]:
                arr[i, 2] = r
                changed = True
            if arr[i, 2] < 1e-9:
                arr[i, 2] = 1e-9
        if not changed:
            break
    return arr


def _slsqp(arr, cons, maxiter=600, ftol=1e-14):
    n = arr.shape[0]
    bounds = [(0.0, 1.0)] * (3 * n)
    for i in range(n):
        bounds[3 * i + 2] = (1e-6, 0.5)
    v0 = arr.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-6, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return _unpack(res.x).copy()
    except Exception:
        pass
    return arr.copy()


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A.append(row)
            b.append(d)
    A = np.array(A)
    b = np.array(b)
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _fps_select(points, n):
    pts = np.array(points, dtype=float)
    if len(pts) <= n:
        idx = np.arange(len(pts))
        reps = (n + len(pts) - 1) // len(pts)
        return pts[np.tile(idx, reps)[:n]]
    chosen = [0]
    d = np.hypot(pts[:, 0] - pts[0, 0], pts[:, 1] - pts[0, 1])
    for _ in range(n - 1):
        idx = int(np.argmax(d))
        chosen.append(idx)
        nd = np.hypot(pts[:, 0] - pts[idx, 0], pts[:, 1] - pts[idx, 1])
        d = np.minimum(d, nd)
    return pts[chosen]


def _lattice_seeds(n):
    seeds = []
    for s in np.linspace(0.15, 0.30, 20):
        pts = []
        h = s * np.sqrt(3.0) / 2.0
        jmax = int(np.ceil(1.0 / h)) + 2
        imax = int(np.ceil(1.0 / s)) + 2
        for j in range(-1, jmax):
            y = j * h
            xoff = (s / 2.0) if (j % 2) else 0.0
            for i in range(-1, imax):
                x = i * s + xoff
                if 0.0 <= x <= 1.0 and 0.0 <= y <= 1.0:
                    pts.append((x, y))
        if len(pts) >= n:
            seeds.append(_fps_select(pts, n))
    rng = np.random.default_rng(777)
    for s in np.linspace(0.15, 0.30, 8):
        pts = []
        imax = int(np.ceil(1.0 / s)) + 2
        for j in range(-1, imax):
            for i in range(-1, imax):
                x = i * s
                y = j * s
                if 0.0 <= x <= 1.0 and 0.0 <= y <= 1.0:
                    pts.append((x, y))
        if len(pts) >= n:
            base = _fps_select(pts, n)
            jitter = base + rng.normal(0.0, s * 0.12, size=base.shape)
            jitter = np.clip(jitter, 0.0, 1.0)
            seeds.append(jitter)
    return seeds


def _centers_to_arr(centers):
    r = _lp_radii(centers)
    arr = np.column_stack([centers, r])
    return _feasible(arr)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)
    deadline = budget_seconds * 0.88

    def elapsed():
        return time.process_time() - t0

    candidates = []

    if start is not None:
        try:
            base = np.asarray(start, dtype=float).copy()
            if base.shape == (n, 3):
                candidates.append(_feasible(base))
        except Exception:
            pass

    for centers in _lattice_seeds(n):
        if elapsed() > deadline * 0.35:
            break
        try:
            candidates.append(_centers_to_arr(centers))
        except Exception:
            pass

    if not candidates:
        centers = _fps_select(np.random.default_rng(0).uniform(0, 1, (400, 2)), n)
        candidates.append(_centers_to_arr(centers))

    # Score by LP objective first
    best = None
    best_score = -1
    for arr in candidates:
        s = np.sum(arr[:, 2])
        if s > best_score:
            best_score = s
            best = arr

    # Polish top few with SLSQP
    candidates.sort(key=lambda a: -np.sum(a[:, 2]))
    top = candidates[:3]
    for arr in top:
        if elapsed() > deadline * 0.5:
            break
        try:
            cand = _slsqp(arr, cons, 400)
            if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
                best = cand
        except Exception:
            pass

    rng = np.random.default_rng(20240101)
    sigmas = [0.02, 0.012, 0.006, 0.003, 0.0015, 0.009]
    try:
        while elapsed() < deadline:
            arr = best.copy()
            s = sigmas[int(rng.integers(0, len(sigmas)))]
            arr[:, 0:2] += rng.normal(0, s, (n, 2))
            arr[:, 2] += rng.normal(0, s * 0.4, n)
            arr = _feasible(arr)
            cand = _slsqp(arr, cons, 300)
            if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
                best = cand
    except Exception:
        pass

    out = best.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out = _feasible(out)
    out[:, 2] = np.maximum(out[:, 2] - 1e-10, 1e-10)
    return out

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
