        for i in range(n):
            r = arr[i, 2]
            arr[i, 2] = min(r, arr[i, 0], 1 - arr[i, 0], arr[i, 1], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    try:
        res = linprog(c, A_ub=np.array(A), b_ub=np.array(b),
                      bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _pair(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj
    return dx*dx + dy*dy - (ri + rj)**2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _jac_wx(v, i):
    g = np.zeros_like(v); g[3*i] = 1.0; g[3*i+2] = -1.0; return g

def _jac_wx2(v, i):
    g = np.zeros_like(v); g[3*i] = -1.0; g[3*i+2] = -1.0; return g

def _jac_wy(v, i):
    g = np.zeros_like(v); g[3*i+1] = 1.0; g[3*i+2] = -1.0; return g

def _jac_wy2(v, i):
    g = np.zeros_like(v); g[3*i+1] = -1.0; g[3*i+2] = -1.0; return g


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i] - v[3*i+2]), 'jac': (lambda v, i=i: _jac_wx(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]), 'jac': (lambda v, i=i: _jac_wx2(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]), 'jac': (lambda v, i=i: _jac_wy(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]), 'jac': (lambda v, i=i: _jac_wy2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq', 'fun': (lambda v, i=i, j=j: _pair(v, i, j)), 'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _polish(centers, r):
    n = centers.shape[0]
    r = r.copy()
    for _ in range(300):
        violated = False
        for i in range(n):
            x, y = centers[i]
            for dist in (x, 1.0 - x, y, 1.0 - y):
                if r[i] > dist:
                    r[i] -= (r[i] - dist) + 1e-15
                    violated = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr; r[j] -= corr
                    violated = True
        if not violated:
            break
    return r


def _lattice_seeds(n, rng):
    seeds = []
    for s in np.linspace(0.17, 0.26, 12):
        h = s * np.sqrt(3.0) / 2.0
        pts = []
        for j in range(-1, int(np.ceil(1.0 / h)) + 2):
            y = j * h
            xoff = (s / 2.0) if (j % 2) else 0.0
            for i in range(-1, int(np.ceil(1.0 / s)) + 2):
                x = i * s + xoff
                if 0.0 <= x <= 1.0 and 0.0 <= y <= 1.0:
                    pts.append((x, y))
        if len(pts) >= n:
            pts = np.array(pts)
            chosen = [0]
            d = np.hypot(pts[:, 0] - pts[0, 0], pts[:, 1] - pts[0, 1])
            for _ in range(n - 1):
                idx = int(np.argmax(d))
                chosen.append(idx)
                nd = np.hypot(pts[:, 0] - pts[idx, 0], pts[:, 1] - pts[idx, 1])
                d = np.minimum(d, nd)
            seeds.append(pts[chosen])
    return seeds


def _random_seed(n, rng):
    pts = rng.random((n, 2))
    return pts


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)
    rng = np.random.default_rng(int(time.process_time() * 1e6) % (2**31))

    if start is not None:
        arr = np.asarray(start, dtype=float).copy()
        if arr.shape != (n, 3):
            arr = _initial()
    else:
        arr = _initial()
    arr = _feasible(arr)
    best = _slsqp(arr, cons, 800)
    if np.sum(best[:, 2]) < np.sum(arr[:, 2]):
        best = arr
    best = _feasible(best)

    # Multi-start with lattice + random seeds
    seeds = _lattice_seeds(n, rng)
    for _ in range(6):
        seeds.append(_random_seed(n, rng))

    for centers in seeds:
        if time.process_time() - t0 >= 0.55 * budget_seconds:
            break
        r = _lp_radii(centers)
        a = _feasible(np.column_stack([centers, r]))
        cand = _slsqp(a, cons, 600)
        cand = _feasible(cand)
        if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
            best = cand

    # Perturbation loop with decreasing noise
    it = 0
    while time.process_time() - t0 < 0.92 * budget_seconds:
        scale = max(0.002, 0.012 * np.exp(-it / 15.0))
        a = best.copy()
        a[:, 0:2] += rng.normal(0.0, scale, size=(n, 2))
        a[:, 2] += rng.normal(0.0, scale * 0.4, size=n)
        a[:, 2] = np.clip(a[:, 2], 1e-6, 0.5)
        a = _feasible(a)
        # LP-based radius re-optimization on perturbed centers
        centers = a[:, :2].copy()
        r = _lp_radii(centers)
        a2 = _feasible(np.column_stack([centers, r]))
        cand = _slsqp(a2, cons, 400)
        cand = _feasible(cand)
        if np.sum(cand[:, 2]) > np.sum(best[:, 2]):
            best = cand
        it += 1
        if it > 60 and time.process_time() - t0 >= 0.90 * budget_seconds:
            break

    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    # final safety: shrink by tiny epsilon to guarantee zero-tolerance validity
    r = np.maximum(r - 1e-12, 1e-9)
    r = _polish(centers, r)
    return np.column_stack([centers, r])

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = max(arr[i, 2], 1e-9)
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(60):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-13
                    arr[j, 2] -= excess * 0.5 + 1e-13
                    changed = True
        for i in range(n):
            arr[i, 2] = min(arr[i, 2], arr[i, 0], 1 - arr[i, 0],
                            arr[i, 1], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    A = np.array(A); b = np.array(b)
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=[(0.0, None)] * n,
                      method='highs')
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return np.full(n, 0.05)


def _pair(v, i, j):
    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
    s = v[3*i+2] + v[3*j+2]
    return dx*dx + dy*dy - s*s


def _pair_jac(v, i, j):
    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
    s = v[3*i+2] + v[3*j+2]
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _jac_wall(v, i, coord, sign):
    g = np.zeros_like(v)
    g[3*i+coord] = sign
    g[3*i+2] = -1.0
    return g


def _build_cons(n, active_v=None, tol=1e-7):
    cons = []
    def mk(kind):
        return kind
    for i in range(n):
        specs = [
            (0, 1.0, lambda v, i=i: v[3*i] - v[3*i+2]),
            (0, -1.0, lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
            (1, 1.0, lambda v, i=i: v[3*i+1] - v[3*i+2]),
            (1, -1.0, lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
        ]
        for coord, sign, fun in specs:
            kind = 'ineq'
            if active_v is not None and fun(active_v) < tol:
                kind = 'eq'
            cons.append({'type': kind, 'fun': fun,
                         'jac': (lambda v, i=i, c=coord, s=sign: _jac_wall(v, i, c, s))})
    for i in range(n):
        for j in range(i + 1, n):
            kind = 'ineq'
            if active_v is not None and _pair(active_v, i, j) < tol:
                kind = 'eq'
            cons.append({'type': kind,
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v); g.reshape(-1, 3)[:, 2] = -1.0; return g


def _slsqp(arr, cons, maxiter, ftol=1e-13):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-7, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-7), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _score(arr):
    return float(np.sum(arr[:, 2]))


def _finalize(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    arr[:, 2] = np.maximum(arr[:, 2] - 1e-8, 1e-8)
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r + 1e-10), 1.0 - r - 1e-10)
        arr[i, 1] = min(max(arr[i, 1], r + 1e-10), 1.0 - r - 1e-10)
    for _ in range(300):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]; dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s + 1e-10:
                    excess = s + 1e-10 - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            arr[i, 2] = min(arr[i, 2], arr[i, 0] - 1e-10, 1.0 - arr[i, 0] - 1e-10,
                            arr[i, 1] - 1e-10, 1.0 - arr[i, 1] - 1e-10)
            arr[i, 2] = max(arr[i, 2], 1e-8)
        if not changed:
            break
    return arr


def _polish(arr, t0, deadline, maxiter=800):
    """Active-set SLSQP polish: run SLSQP, then re-identify active set, repeat."""
    best = arr.copy()
    cons_full = _build_cons(arr.shape[0])
    cand = _slsqp(best, cons_full, maxiter)
    if _score(cand) > _score(best):
        best = cand
    for _ in range(3):
        if time.process_time() - t0 > deadline:
            break
        v = best.reshape(-1)
        cons_act = _build_cons(best.shape[0], active_v=v, tol=1e-5)
        cand = _slsqp(best, cons_act, maxiter)
        if _score(cand) > _score(best):
            best = cand
        else:
            break
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    deadline_hard = 0.94 * budget_seconds

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        if base.shape != (n, 3):
            base = None
    else:
        base = None

    if base is None:
        pts = []
        for j in range(5):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
        pts.append((0.5, 0.5))
        base = np.array([[x, y, 0.09] for x, y in pts], dtype=float)

    best = _feasible(base)

    # LP re-polish radii on current centers, then SLSQP active-set
    r = _lp_radii(best[:, :2])
    arr = _feasible(np.column_stack([best[:, :2], r]))
    best = _polish(arr, t0, 0.35 * budget_seconds, maxiter=1000)

    # Perturbation / basin-hopping loop
    rng = np.random.default_rng(1234567)
    it = 0
    while time.process_time() - t0 < deadline_hard:
        remaining = deadline_hard - (time.process_time() - t0)
        # adaptive sigma schedule
        sigma = 0.008 * (0.985 ** it)
        sigma = max(sigma, 0.0008)

        arr = best.copy()
        k = int(rng.integers(2, n + 1))
        idx = rng.choice(n, size=k, replace=False)
        arr[idx, 0] += rng.normal(0.0, sigma, size=k)
        arr[idx, 1] += rng.normal(0.0, sigma, size=k)
        arr[:, 0] = np.clip(arr[:, 0], 0.0, 1.0)
        arr[:, 1] = np.clip(arr[:, 1], 0.0, 1.0)
        arr = _feasible(arr)

        # re-optimize radii via LP on perturbed centers
        if rng.random() < 0.4:
            r = _lp_radii(arr[:, :2])
            arr = _feasible(np.column_stack([arr[:, :2], r]))

        cand = _slsqp(arr, _build_cons(n), maxiter=200)
        if _score(cand) > _score(best):
            best = _polish(cand, t0, min(deadline_hard, time.process_time() - t0 + 0.5), 300)
        it += 1

        if remaining < 0.35:
            break

    # Final LP + active-set polish
    if time.process_time() - t0 < 0.97 * budget_seconds:
        r = _lp_radii(best[:, :2])
        arr = _feasible(np.column_stack([best[:, :2], r]))
        cand = _slsqp(arr, _build_cons(n), maxiter=600)
        if _score(cand) > _score(best):
            best = cand
        best = _polish(best, t0, 0.985 * budget_seconds, 600)

    return _finalize(best)

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible(arr):
