            r = arr[i, 2]
            arr[i, 2] = min(r, arr[i, 0], 1 - arr[i, 0], arr[i, 1], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    A = np.array(A); b = np.array(b)
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _polish(centers, r):
    n = centers.shape[0]
    r = r.copy()
    for _ in range(300):
        violated = False
        for i in range(n):
            x, y = centers[i, 0], centers[i, 1]
            for dist in (x, 1.0 - x, y, 1.0 - y):
                if r[i] > dist:
                    r[i] = dist
                    violated = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr; r[j] -= corr
                    violated = True
        if not violated:
            break
    return r


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i, 1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i, -1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i+1, 1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i+1, -1.0))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq', 'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _jw(v, k, s):
    g = np.zeros_like(v); g[k] = s; g[k + 2 - (k % 3)] = -1.0
    # simpler: reconstruct
    g = np.zeros_like(v)
    if k % 3 == 0 or k % 3 == 1:
        g[k] = s
        g[k - (k % 3) + 2] = -1.0
    return g


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _pair(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj
    return dx*dx + dy*dy - (ri + rj)**2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
    return np.array([[x, y, 0.09] for x, y in pts], dtype=float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arr = np.asarray(start, dtype=float).copy()
        if arr.shape != (n, 3):
            arr = _initial()
    else:
        arr = _initial()

    arr = _feasible(arr)
    best = _slsqp(arr, cons, 800)
    if np.sum(best[:, 2]) < np.sum(arr[:, 2]):
        best = arr

    # Repeated perturbation + SLSQP polish of the best solution.
    rng = np.random.default_rng(12345)
    it = 0
    best_score = float(np.sum(best[:, 2]))
    while time.process_time() - t0 < 0.92 * budget_seconds:
        it += 1
        cand = best.copy()
        # Vary perturbation scale, occasionally large jumps.
        sigma = 0.03 if (it % 7 == 0) else 0.012
        cand[:, 0] += rng.normal(0.0, sigma, size=n)
        cand[:, 1] += rng.normal(0.0, sigma, size=n)
        cand[:, 2] += rng.normal(0.0, 0.005, size=n)
