        cand = _feasible(cand)
        res = _slsqp(cand, cons, 300)
        sc = float(np.sum(res[:, 2]))
        if sc > best_score + 1e-12:
            best = res
            best_score = sc

    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    r = np.maximum(r * (1.0 - 1e-12), 1e-9)
    r = _polish(centers, r)
    return np.column_stack([centers, r])

