                            cand[:, 1:2] - np.array(chosen)[:, 1][None, :]), axis=1)
        chosen.append(cand[np.argmax(d)])
    return np.array(chosen[:n])


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wx(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wx2(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wy(v, i))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wy2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = np.clip(arr.reshape(-1).copy(), 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _jac_wx(v, i):
    g = np.zeros_like(v); g[3*i] = 1.0; g[3*i+2] = -1.0; return g
def _jac_wx2(v, i):
    g = np.zeros_like(v); g[3*i] = -1.0; g[3*i+2] = -1.0; return g
def _jac_wy(v, i):
    g = np.zeros_like(v); g[3*i+1] = 1.0; g[3*i+2] = -1.0; return g
def _jac_wy2(v, i):
    g = np.zeros_like(v); g[3*i+1] = -1.0; g[3*i+2] = -1.0; return g

def _pair(v, i, j):
    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
    s = v[3*i+2] + v[3*j+2]
    return dx*dx + dy*dy - s*s

def _pair_jac(v, i, j):
    dx = v[3*i] - v[3*j]; dy = v[3*i+1] - v[3*j+1]
    s = v[3*i+2] + v[3*j+2]
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _polish(centers, radii):
    """Exact float-safe polish: shrink radii to satisfy all constraints with margin."""
    c = centers.copy()
    r = radii.copy()
    n = c.shape[0]
    for _ in range(200):
        changed = False
        for i in range(n):
            m = min(c[i, 0], 1 - c[i, 0], c[i, 1], 1 - c[i, 1])
            if r[i] > m:
                r[i] = m
                changed = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = c[i, 0] - c[j, 0]; dy = c[i, 1] - c[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) * 0.5 + 1e-14
                    r[i] -= corr; r[j] -= corr
                    changed = True
        if not changed:
            break
    r = np.maximum(r, 1e-9)
    # Final safety shrink
    r -= 1e-12
    r = np.maximum(r, 1e-9)
    return r


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)

    # Re-optimize from start
    bestA = _slsqp(arrA, cons, 1500, 1e-13)
    if np.sum(bestA[:, 2]) < np.sum(arrA[:, 2]):
        bestA = arrA
    best = bestA.copy()
    best_score = np.sum(best[:, 2])

    # Multi-start from random FPS placements
    rng = np.random.default_rng(20241207)
    results = []
    n_starts = 40
    for k in range(n_starts):
        if time.process_time() - t0 > 0.65 * budget_seconds:
            break
        centers = _fps_centers_random(n, rng, grid=60)
        radii = _lp_radii(centers)
        arrB = _feasible(np.column_stack([centers, radii]))
        cand = _slsqp(arrB, cons, 600, 1e-12)
        if np.sum(cand[:, 2]) < np.sum(arrB[:, 2]):
            cand = arrB
        sc = np.sum(cand[:, 2])
        results.append((sc, cand))
        if sc > best_score:
            best_score = sc
            best = cand.copy()

    # Exploit remaining time: refine top starts
    results.sort(key=lambda t: -t[0])
    for sc, arr in results[:6]:
        if time.process_time() - t0 > 0.90 * budget_seconds:
            break
        cand = _slsqp(arr, cons, 2500, 1e-13)
        if np.sum(cand[:, 2]) > np.sum(arr[:, 2]):
            arr = cand
        sc2 = np.sum(arr[:, 2])
        if sc2 > best_score:
            best_score = sc2
            best = arr.copy()

    # Final polish with LP radii then exact shrink
    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    return np.column_stack([centers, r])

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
    r0 = 0.09
    return np.array([[x, y, r0] for x, y in pts], dtype=float)


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(60):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            if arr[i, 0] - r < 0: arr[i, 2] = arr[i, 0]
            if 1 - arr[i, 0] - r < 0: arr[i, 2] = 1 - arr[i, 0]
            if arr[i, 1] - r < 0: arr[i, 2] = min(arr[i, 2], arr[i, 1])
            if 1 - arr[i, 1] - r < 0: arr[i, 2] = min(arr[i, 2], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []; b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    A = np.array(A); b = np.array(b)
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, i, 3*i, 1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, i, 3*i, -1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, i, 3*i+1, 1.0))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, i, 3*i+1, -1.0))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _build_cons_active(n, arr, tol=1e-7):
    v = arr.reshape(-1)
    cons = []
    for i in range(n):
        for (idx, sign) in ((3*i, 1.0), (3*i, -1.0), (3*i+1, 1.0), (3*i+1, -1.0)):
            slack = (v[idx] - v[3*i+2]) if sign > 0 else (1.0 - v[idx] - v[3*i+2])
            cons.append({'type': 'eq' if slack < tol else 'ineq',
                         'fun': (lambda v, idx=idx, i=i, sign=sign: (v[idx] - v[3*i+2]) if sign > 0 else (1.0 - v[idx] - v[3*i+2])),
                         'jac': (lambda v, idx=idx, i=i, sign=sign: _jw(v, i, idx, sign))})
    for i in range(n):
        for j in range(i + 1, n):
            slack = _pair(v, i, j)
            cons.append({'type': 'eq' if slack < tol else 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _jw(v, i, idx, sign):
    g = np.zeros_like(v)
    g[idx] = sign
    g[3*i+2] = -1.0
    return g


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = np.clip(arr.reshape(-1).copy(), 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _polish(centers, r):
    n = centers.shape[0]
    r = r.copy()
    for _ in range(300):
        violated = False
        for i in range(n):
            x, y = centers[i, 0], centers[i, 1]
            for dist in (x, 1.0 - x, y, 1.0 - y):
                if r[i] > dist:
                    r[i] -= (r[i] - dist) + 1e-15
                    violated = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr; r[j] -= corr
                    violated = True
        if not violated:
            break
    return r


def _best_empty_point(kept, grid=60):
    xs = (np.arange(grid) + 0.5) / grid
    X, Y = np.meshgrid(xs, xs)
    pts = np.column_stack([X.ravel(), Y.ravel()])
    wall = np.minimum(np.minimum(pts[:, 0], 1.0 - pts[:, 0]),
                      np.minimum(pts[:, 1], 1.0 - pts[:, 1]))
    if len(kept) > 0:
        kc = np.array(kept, dtype=float)
        dx = pts[:, 0:1] - kc[None, :, 0]
        dy = pts[:, 1:2] - kc[None, :, 1]
        d = np.hypot(dx, dy) - kc[None, :, 2]
        score = np.minimum(wall, np.min(d, axis=1))
    else:
        score = wall
    idx = int(np.argmax(score))
    return pts[idx, 0], pts[idx, 1], max(score[idx], 1e-6)


def _ruin_recreate(best, cons, t0, budget, rng):
    n = best.shape[0]
    stall = 0
    while time.process_time() - t0 < 0.85 * budget:
        if rng.random() < 0.35:
            order = np.argsort(best[:, 2])
            S = list(order[:6])
        else:
            k = int(rng.integers(2, 6))
            seed = int(rng.integers(0, n))
            d = np.hypot(best[:, 0] - best[seed, 0], best[:, 1] - best[seed, 1])
            order = np.argsort(d)
            S = [int(idx) for idx in order[:k]]
        Sset = set(S)
        kept = [best[i] for i in range(n) if i not in Sset]
        cand = best.copy()
        order_S = list(S); rng.shuffle(order_S)
        for i in order_S:
            x, y, r = _best_empty_point(kept, grid=60)
            cand[i, 0] = x; cand[i, 1] = y; cand[i, 2] = r
            kept.append(cand[i].copy())
        cand = _feasible(cand)
        res = _slsqp(cand, cons, 500)
        if np.sum(res[:, 2]) > np.sum(best[:, 2]) + 1e-12:
            best = res; stall = 0
        else:
            stall += 1
            if stall > 40 and time.process_time() - t0 < 0.6 * budget:
                # extra kick: perturb everything
                cand = best.copy()
                cand[:, 0] += rng.normal(0, 0.03, n)
                cand[:, 1] += rng.normal(0, 0.03, n)
                cand[:, 2] += rng.normal(0, 0.003, n)
                cand = _feasible(cand)
                res = _slsqp(cand, cons, 800)
                if np.sum(res[:, 2]) > np.sum(best[:, 2]) + 1e-12:
                    best = res
                stall = 0
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arrA = np.asarray(start, dtype=float).copy()
        if arrA.shape != (n, 3):
            arrA = _initial()
    else:
        arrA = _initial()
    arrA = _feasible(arrA)
    bestA = _slsqp(arrA, cons, 1200)
    if _obj(bestA.reshape(-1)) > _obj(arrA.reshape(-1)):
        bestA = arrA

    # Active-set refinement: treat touching constraints as equalities for a
    # sharper SLSQP step. This is the key extra push near the optimum.
    if time.process_time() - t0 < 0.5 * budget_seconds:
        cons_act = _build_cons_active(n, bestA, tol=1e-7)
        cand = _slsqp(bestA, cons_act, 3000, 1e-14)
        if _obj(cand.reshape(-1)) < _obj(bestA.reshape(-1)):
            bestA = cand

    best = bestA
    rng = np.random.default_rng(12345)
    best = _ruin_recreate(best, cons, t0, budget_seconds, rng)

    # Final active-set polish
    if time.process_time() - t0 < 0.92 * budget_seconds:
        cons_act = _build_cons_active(n, best, tol=1e-7)
        cand = _slsqp(best, cons_act, 2000, 1e-14)
        if _obj(cand.reshape(-1)) < _obj(best.reshape(-1)):
            best = cand

    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    # Safety shrink
    r = np.maximum(r - 1e-11, 1e-9)
    return np.column_stack([centers, r])


def _pair(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj
    return dx*dx + dy*dy - (ri + rj)**2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
