    n = centers.shape[0]
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    dx = centers[:, 0][:, None] - centers[:, 0][None, :]
    dy = centers[:, 1][:, None] - centers[:, 1][None, :]
    D = np.hypot(dx, dy)
    for i in range(n):
        for j in range(i + 1, n):
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(D[i, j])
    try:
        res = linprog(-np.ones(n), A_ub=np.array(A), b_ub=np.array(b),
                      bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i, 3*i+2, 1.0, -1.0))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i, 3*i+2, -1.0, -1.0))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i+1, 3*i+2, 1.0, -1.0))})
        cons.append({'type': 'ineq',
                     'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jw(v, 3*i+1, 3*i+2, -1.0, -1.0))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _jw(v, ia, ib, ca, cb):
    g = np.zeros_like(v); g[ia] = ca; g[ib] = cb; return g


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = np.clip(arr.reshape(-1).copy(), 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _pair(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj
    return dx*dx + dy*dy - (ri + rj)**2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _safe_fix(centers, r, iters=200):
    """Shrink radii to guarantee feasibility in exact float arithmetic."""
    n = len(r)
    r = r.astype(float).copy()
    for _ in range(iters):
        changed = False
        for i in range(n):
            x, y = centers[i]
            m = min(x, 1.0 - x, y, 1.0 - y)
            if r[i] > m:
                r[i] = m - 1e-12
                changed = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) * 0.5 + 1e-12
                    r[i] -= corr; r[j] -= corr
                    changed = True
        if not changed:
            break
    return np.maximum(r, 1e-10)


def _grid_seed(n, rng, jitter=0.0):
    # Hexagonal-ish lattice seed with spacing chosen to fit ~n cells
    s = np.sqrt(1.0 / n) * 1.0
    h = s * np.sqrt(3.0) / 2.0
    pts = []
    jmax = int(np.ceil(1.0 / h)) + 2
    imax = int(np.ceil(1.0 / s)) + 2
    for j in range(jmax):
        y = (j + 0.5) * h
        if y > 1.0:
            y = 1.0 - 1e-6
        xoff = (s / 2.0) if (j % 2) else 0.0
        for i in range(imax):
            x = i * s + xoff + 0.5 * s
            if 0.0 < x < 1.0:
                pts.append((x, y))
    if len(pts) < n:
        # fallback: random
        while len(pts) < n:
            pts.append((rng.uniform(0.05, 0.95), rng.uniform(0.05, 0.95)))
    pts = np.array(pts[:n])
    if jitter > 0:
        pts = pts + rng.normal(0.0, jitter, size=pts.shape)
        pts = np.clip(pts, 0.02, 0.98)
    return pts


def _fps(points, n):
    pts = np.array(points, dtype=float)
    if len(pts) <= n:
        while len(pts) < n:
            pts = np.vstack([pts, pts[0]])
        return pts[:n]
    chosen = [0]
    d = np.hypot(pts[:, 0] - pts[0, 0], pts[:, 1] - pts[0, 1])
    for _ in range(n - 1):
        idx = int(np.argmax(d))
        chosen.append(idx)
        nd = np.hypot(pts[:, 0] - pts[idx, 0], pts[:, 1] - pts[idx, 1])
        d = np.minimum(d, nd)
    return pts[chosen]


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    deadline = budget_seconds * 0.85
    cons = _build_cons(n)

    best = None
    best_score = -1.0

    def consider(arr):
        nonlocal best, best_score
        arr = np.asarray(arr, dtype=float)
        centers = arr[:, :2].copy()
        r = _lp_radii(centers)
        r = _safe_fix(centers, r)
        sc = float(np.sum(r))
        if sc > best_score:
            best_score = sc
            best = np.column_stack([centers, r])

    # Start from provided start
    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        if s.shape == (n, 3):
            consider(s)
            # Polish start via SLSQP
            cand = _slsqp(s, cons, 1500)
            consider(cand)

    # Baseline initial
    init = _initial()
    consider(init)

    # Multi-start search
    rng = np.random.default_rng(None)
    trials = 0
    while time.process_time() - t0 < deadline:
        trials += 1
        # Mix: lattice seed with jitter, or pure random
        if trials % 3 == 0:
            centers = rng.uniform(0.05, 0.95, size=(n, 2))
        else:
            jit = 0.0 if trials % 2 else 0.03
            pts = _grid_seed(n * 3, rng, jitter=jit)
            centers = _fps(pts, n)
        r = _lp_radii(centers)
        arr = np.column_stack([centers, r])
        cand = _slsqp(arr, cons, 400, 1e-11)
        consider(cand)
        if time.process_time() - t0 > deadline:
            break

    # Intensify best solution
    if best is not None:
        for ftol in (1e-12, 1e-13, 1e-14):
            if time.process_time() - t0 > deadline * 1.05:
                break
            cand = _slsqp(best, cons, 3000, ftol)
            consider(cand)

    # If no start and nothing better, fall back to start
    if best is None:
        if start is not None:
            best = np.asarray(start, dtype=float).copy()
        else:
            best = _initial()

    # Final safety: exact feasibility
    centers = best[:, :2].copy()
    r = _safe_fix(centers, best[:, 2])
    return np.column_stack([centers, r])

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(80):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-13
                    arr[j, 2] -= excess * 0.5 + 1e-13
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            arr[i, 2] = min(arr[i, 2], arr[i, 0], 1 - arr[i, 0], arr[i, 1], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    A = np.array(A); b = np.array(b)
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_x(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_x2(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_y(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_y2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq',
                         'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0)); bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _jac_wall_x(v, i):
    g = np.zeros_like(v); g[3*i] = 1.0; g[3*i+2] = -1.0; return g
def _jac_wall_x2(v, i):
    g = np.zeros_like(v); g[3*i] = -1.0; g[3*i+2] = -1.0; return g
def _jac_wall_y(v, i):
    g = np.zeros_like(v); g[3*i+1] = 1.0; g[3*i+2] = -1.0; return g
def _jac_wall_y2(v, i):
    g = np.zeros_like(v); g[3*i+1] = -1.0; g[3*i+2] = -1.0; return g


def _pair(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj
    return dx*dx + dy*dy - (ri + rj)**2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _score(arr):
    return float(np.sum(arr[:, 2]))


def _contact_forces(arr):
    """Compute per-circle 'pressure' = number of near-active constraints.
    Used to identify circles that can shrink to let others grow."""
    n = arr.shape[0]
    force = np.zeros(n)
    for i in range(n):
        x, y, r = arr[i]
        for dist in (x, 1-x, y, 1-y):
            if r - dist > -1e-6:
                force[i] += 1.0
    for i in range(n):
        for j in range(i+1, n):
            dx = arr[i,0]-arr[j,0]; dy = arr[i,1]-arr[j,1]
            d = np.hypot(dx, dy)
            s = arr[i,2]+arr[j,2]
            if d - s < 1e-6:
                force[i] += 1.0; force[j] += 1.0
    return force


def _perturb_radii(arr, rng, scale):
    """Perturb radii directly; then project to feasibility via _feasible."""
    out = arr.copy()
    out[:, 2] = np.maximum(out[:, 2] + rng.normal(0.0, scale, size=out.shape[0]), 1e-6)
    return _feasible(out)


def _perturb_centers_lp(arr, rng, scale):
    out = arr.copy()
    out[:, 0:2] += rng.normal(0.0, scale, size=(out.shape[0], 2))
    out[:, 0:2] = np.clip(out[:, 0:2], 1e-3, 1.0 - 1e-3)
    centers = out[:, :2]
    r = _lp_radii(centers)
    return np.column_stack([centers, r])


def _final_safe(arr):
    """Shrink radii and re-center to guarantee zero-tolerance feasibility."""
    arr = arr.copy()
    n = arr.shape[0]
    # shrink all radii by a tiny safety margin relative to size
    arr[:, 2] = np.maximum(arr[:, 2] * (1.0 - 1e-9) - 1e-12, 1e-9)
    # clamp centers into feasible box
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    # iteratively push apart / shrink to remove any residual violation
    for _ in range(200):
        worst = 0.0
        for i in range(n):
            xi, yi, ri = arr[i]
            for dist in (xi, 1.0 - xi, yi, 1.0 - yi):
                worst = max(worst, ri - dist)
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if s - d > worst:
                    worst = s - d
        if worst <= 0.0:
            break
        # shrink all radii a bit
        arr[:, 2] = np.maximum(arr[:, 2] - (worst * 0.5 + 1e-14), 1e-12)
        for i in range(n):
            r = arr[i, 2]
            arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
            arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    return arr


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arr = np.asarray(start, dtype=float).copy()
        if arr.shape != (n, 3):
            arr = None
    else:
        arr = None

    if arr is None:
        # fallback grid
        pts = []
        for j in range(5):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
        pts.append((0.5, 0.5))
        arr = np.array([[x, y, 0.09] for x, y in pts], dtype=float)

    arr = _feasible(arr)
    best = _slsqp(arr, cons, 1500)
    if _score(best) < _score(arr):
        best = arr

    # LP polish
    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    cand = np.column_stack([centers, r])
    if _score(cand) > _score(best):
        best = cand

    rng = np.random.default_rng(987654321)
    cur = best.copy()
    cur_score = _score(cur)
    best_score = cur_score

    # Mixed perturbation basin hopping: alternate radii-perturbation (cheap, exploits
    # active-set structure) with center-perturbation+LP (explores new configurations).
    it = 0
    while time.process_time() - t0 < 0.85 * budget_seconds:
        frac = (time.process_time() - t0) / budget_seconds
        use_radii = (it % 3 != 0)  # mostly radii, occasionally centers

        if use_radii:
            scale = 0.012 * (1.0 - frac) + 0.001 * frac
            trial = _perturb_radii(cur, rng, scale)
            trial = _slsqp(trial, cons, 200, 1e-12)
        else:
            scale = 0.02 * (1.0 - frac) + 0.002 * frac
            trial = _perturb_centers_lp(cur, rng, scale)
            trial = _slsqp(trial, cons, 200, 1e-12)

        sc = _score(trial)
        if sc > best_score + 1e-10:
            best = trial; best_score = sc
            cur = trial; cur_score = sc
        elif sc > cur_score - 2e-4:
            cur = trial; cur_score = sc
        else:
            # restart from best occasionally
            if rng.random() < 0.5:
                cur = best.copy(); cur_score = best_score
        it += 1

    # Final: LP on best centers then a full SLSQP
    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    arr = np.column_stack([centers, r])
    arr2 = _slsqp(arr, cons, 300, 1e-14)
    if _score(arr2) > _score(arr):
        arr = arr2

    return _final_safe(arr)

