import numpy as np
import time
from scipy.optimize import minimize, linprog


def _initial():
    pts = []
    for j in range(5):
        for i in range(5):
            pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
    pts.append((0.5, 0.5))
    return np.array([[x, y, 0.09] for x, y in pts], dtype=float)


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = max(arr[i, 2], 1e-9)
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(60):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]; dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy); s = arr[i, 2] + arr[j, 2]
                if d < s:
                    e = s - d
                    arr[i, 2] -= e * 0.5 + 1e-13
                    arr[j, 2] -= e * 0.5 + 1e-13
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            arr[i, 2] = min(arr[i, 2], arr[i, 0], 1 - arr[i, 0], arr[i, 1], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []; b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n); row[i] = 1.0
        A.append(row); b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n); row[i] = 1.0; row[j] = 1.0
            A.append(row); b.append(d)
    try:
        res = linprog(c, A_ub=np.array(A), b_ub=np.array(b),
                      bounds=[(0.0, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return np.full(n, 0.05)


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v); g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _jac_wall_x(v, i):
    g = np.zeros_like(v); g[3 * i] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_x2(v, i):
    g = np.zeros_like(v); g[3 * i] = -1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0; return g

def _jac_wall_y2(v, i):
    g = np.zeros_like(v); g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0; return g

def _pair(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj
    return dx*dx + dy*dy - (ri+rj)**2

def _pair_jac(v, i, j):
    xi, yi, ri = v[3*i], v[3*i+1], v[3*i+2]
    xj, yj, rj = v[3*j], v[3*j+1], v[3*j+2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3*i] = 2*dx; g[3*i+1] = 2*dy; g[3*i+2] = -2*s
    g[3*j] = -2*dx; g[3*j+1] = -2*dy; g[3*j+2] = -2*s
    return g


def _build_cons(n):
    cons = []
    for i in range(n):
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_x(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_x2(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_y(v, i))})
        cons.append({'type': 'ineq', 'fun': (lambda v, i=i: 1.0 - v[3*i+1] - v[3*i+2]),
                     'jac': (lambda v, i=i: _jac_wall_y2(v, i))})
    for i in range(n):
        for j in range(i + 1, n):
            cons.append({'type': 'ineq', 'fun': (lambda v, i=i, j=j: _pair(v, i, j)),
                         'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    return cons


def _slsqp(arr, cons, maxiter, ftol=1e-12):
    n = arr.shape[0]
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0)); bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))
    v0 = arr.reshape(-1).copy()
    v0 = np.clip(v0, 0.0, 1.0)
    for i in range(n):
        v0[3*i+2] = min(max(v0[3*i+2], 1e-6), 0.5)
    try:
        res = minimize(_obj, v0, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(-1, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _polish(centers, r):
    n = centers.shape[0]
    r = r.copy()
    for _ in range(300):
        viol = False
        for i in range(n):
            x, y = centers[i, 0], centers[i, 1]
            for dist in (x, 1.0 - x, y, 1.0 - y):
                if r[i] > dist:
                    r[i] = dist - 1e-15
                    viol = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy); s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr; r[j] -= corr
                    viol = True
        r = np.maximum(r, 1e-9)
        if not viol:
            break
    return r


def _max_radius_at(cx, cy, fxy, fr):
    w = min(cx, 1.0 - cx, cy, 1.0 - cy)
    if fxy.shape[0] > 0:
        d = np.hypot(fxy[:, 0] - cx, fxy[:, 1] - cy) - fr
        m = float(np.min(d))
        if m < w:
            w = m
    return w


def _ruin_recreate(best, cons, t0, budget, rng, grid=50):
    n = best.shape[0]
    gx = (np.arange(grid) + 0.5) / grid
    GX, GY = np.meshgrid(gx, gx)
    grid_pts = np.column_stack([GX.ravel(), GY.ravel()])
    best_sum = float(np.sum(best[:, 2]))
    while time.process_time() - t0 < budget:
        k = 1 if rng.random() < 0.6 else (2 if rng.random() < 0.8 else 3)
        if rng.random() < 0.5:
            w = 1.0 / np.maximum(best[:, 2], 1e-9); w /= w.sum()
            victims = list(rng.choice(n, size=k, replace=False, p=w))
        else:
            victims = list(rng.choice(n, size=k, replace=False))
        keep = np.ones(n, dtype=bool); keep[victims] = False
        ki = np.where(keep)[0]
        cand = best.copy()
        placed_xy = []; placed_r = []
        for vi in victims:
            all_pts = np.vstack([grid_pts, best[vi, :2][None, :],
                                 rng.random((100, 2))])
            fx = best[ki, :2]; fr = best[ki, 2]
            if placed_xy:
                fx = np.vstack([fx, np.array(placed_xy)])
                fr = np.concatenate([fr, np.array(placed_r)])
            w = np.minimum(np.minimum(all_pts[:, 0], 1.0 - all_pts[:, 0]),
                           np.minimum(all_pts[:, 1], 1.0 - all_pts[:, 1]))
            if fx.shape[0] > 0:
                dx = all_pts[:, 0:1] - fx[None, :, 0]
                dy = all_pts[:, 1:2] - fx[None, :, 1]
                dd = np.sqrt(dx*dx + dy*dy) - fr[None, :]
                w = np.minimum(w, np.min(dd, axis=1))
            bi = int(np.argmax(w))
            cand[vi, 0] = all_pts[bi, 0]; cand[vi, 1] = all_pts[bi, 1]
            cand[vi, 2] = max(w[bi], 1e-6)
            placed_xy.append((cand[vi, 0], cand[vi, 1]))
            placed_r.append(cand[vi, 2])
        cand = _feasible(cand)
        res = _slsqp(cand, cons, 200)
        s = float(np.sum(res[:, 2]))
        if s > best_sum + 1e-13:
            best = res; best_sum = s
    return best


def _basin_hop(best, cons, t0, budget, rng):
    n = best.shape[0]
    best_sum = float(np.sum(best[:, 2]))
    it = 0
    while time.process_time() - t0 < budget:
        it += 1
        sigma_c = 0.03 if (it % 4 == 0) else 0.012
        cand = best.copy()
        cand[:, 0] += rng.normal(0.0, sigma_c, size=n)
        cand[:, 1] += rng.normal(0.0, sigma_c, size=n)
        cand[:, 2] += rng.normal(0.0, 0.003, size=n)
        cand[:, 2] = np.maximum(cand[:, 2], 1e-6)
        for i in range(n):
            r = cand[i, 2]
            cand[i, 0] = min(max(cand[i, 0], r), 1.0 - r)
            cand[i, 1] = min(max(cand[i, 1], r), 1.0 - r)
        cand = _feasible(cand)
        res = _slsqp(cand, cons, 300)
        s = float(np.sum(res[:, 2]))
        if s > best_sum + 1e-13:
            best = res; best_sum = s
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    cons = _build_cons(n)

    if start is not None:
        arr = np.asarray(start, dtype=float).copy()
        if arr.shape != (n, 3):
            arr = _initial()
    else:
        arr = _initial()
    arr = _feasible(arr)
    best = _slsqp(arr, cons, 1500)
    if np.sum(best[:, 2]) < np.sum(arr[:, 2]):
        best = arr

    # Reserve time: 55% ruin&recreate, rest basin hop
    rng = np.random.default_rng(20240)
    t_rr = t0 + 0.55 * budget_seconds
    if time.process_time() - t0 < t_rr - t0:
        best = _ruin_recreate(best, cons, t0, t_rr, rng, grid=50)

    best = _basin_hop(best, cons, t0, t0 + 0.92 * budget_seconds, rng)

    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    r = np.maximum(r, 1e-9)
    # final safety: shrink slightly to guarantee zero-tolerance feasibility
    r = r * (1.0 - 1e-12) - 1e-13
    r = np.maximum(r, 1e-9)
    return np.column_stack([centers, r])

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible(arr):
    arr = np.asarray(arr, dtype=float).copy()
    n = arr.shape[0]
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1.0 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1.0 - r)
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s:
                    excess = s - d
                    arr[i, 2] -= excess * 0.5 + 1e-12
                    arr[j, 2] -= excess * 0.5 + 1e-12
                    changed = True
        for i in range(n):
            r = arr[i, 2]
            if arr[i, 0] - r < 0:
                arr[i, 2] = arr[i, 0]
            if 1 - arr[i, 0] - r < 0:
                arr[i, 2] = 1 - arr[i, 0]
            if arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], arr[i, 1])
            if 1 - arr[i, 1] - r < 0:
                arr[i, 2] = min(arr[i, 2], 1 - arr[i, 1])
            arr[i, 2] = max(arr[i, 2], 1e-9)
        if not changed:
            break
    return arr


def _lp_radii(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        x, y = centers[i]
        w = min(x, 1 - x, y, 1 - y)
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A.append(row)
            b.append(d)
    A = np.array(A)
    b = np.array(b)
    bounds = [(0.0, None)] * n
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return np.full(n, 0.05)


# ---------- vectorized penalty solver (fast) ----------
def _penalty_fg(v, n, w=1e3):
    X = v.reshape(n, 3)
    x = X[:, 0]; y = X[:, 1]; r = X[:, 2]
    f = -np.sum(r)
    G = np.zeros((n, 3))
    G[:, 2] = -1.0
    for sign, comp in ((-1.0, 0), (1.0, 0), (-1.0, 1), (1.0, 1)):
        if comp == 0:
            a = r - (x if sign < 0 else 1.0 - x)
        else:
            a = r - (y if sign < 0 else 1.0 - y)
        m = a > 0
        if np.any(m):
            f += w * np.sum(a[m] ** 2)
            G[m, 2] += 2 * w * a[m]
            G[m, comp] += -2 * w * a[m] * sign
    dx = x[:, None] - x[None, :]
    dy = y[:, None] - y[None, :]
    d = np.sqrt(dx * dx + dy * dy)
    s = r[:, None] + r[None, :]
    a = s - d
    iu = np.triu_indices(n, 1)
    av = a[iu]
    m = av > 0
    if np.any(m):
        ii = iu[0][m]; jj = iu[1][m]
        avm = av[m]
        f += w * np.sum(avm ** 2)
        dvals = np.maximum(d[ii, jj], 1e-12)
        dxv = dx[ii, jj]; dyv = dy[ii, jj]
        coef = 2.0 * w * avm
        G[ii, 0] += -coef * dxv / dvals
        G[jj, 0] += coef * dxv / dvals
        G[ii, 1] += -coef * dyv / dvals
        G[jj, 1] += coef * dyv / dvals
        G[ii, 2] += coef
        G[jj, 2] += coef
    return f, G.reshape(-1)


def _penalty_solve(v0, n, iters=400):
    v0 = np.asarray(v0, dtype=float).reshape(-1).copy()
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))
    try:
        res = minimize(_penalty_fg, v0, args=(n,), jac=True, method='L-BFGS-B',
                       bounds=bounds, options={'maxiter': iters, 'maxfun': iters * 3})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(n, 3).copy()
    except Exception:
        pass
    return v0.reshape(n, 3).copy()


# ---------- SLSQP with only active constraints (fast local polish) ----------
def _pair_cons(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj
    return dx * dx + dy * dy - (ri + rj) ** 2


def _pair_jac(v, i, j):
    xi, yi, ri = v[3 * i], v[3 * i + 1], v[3 * i + 2]
    xj, yj, rj = v[3 * j], v[3 * j + 1], v[3 * j + 2]
    dx = xi - xj; dy = yi - yj; s = ri + rj
    g = np.zeros_like(v)
    g[3 * i] = 2 * dx; g[3 * i + 1] = 2 * dy; g[3 * i + 2] = -2 * s
    g[3 * j] = -2 * dx; g[3 * j + 1] = -2 * dy; g[3 * j + 2] = -2 * s
    return g


def _wall_jacs(v, i, which):
    g = np.zeros_like(v)
    if which == 0:
        g[3 * i] = 1.0; g[3 * i + 2] = -1.0
    elif which == 1:
        g[3 * i] = -1.0; g[3 * i + 2] = -1.0
    elif which == 2:
        g[3 * i + 1] = 1.0; g[3 * i + 2] = -1.0
    else:
        g[3 * i + 1] = -1.0; g[3 * i + 2] = -1.0
    return g


def _obj(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _obj_grad(v):
    g = np.zeros_like(v)
    g.reshape(-1, 3)[:, 2] = -1.0
    return g


def _slsqp(arr, maxiter, active_tol=1e-6, ftol=1e-13):
    n = arr.shape[0]
    v = arr.reshape(-1).copy()
    v = np.clip(v, 0.0, 1.0)
    for i in range(n):
        v[3 * i + 2] = min(max(v[3 * i + 2], 1e-6), 0.5)
    cons = []
    for i in range(n):
        x = v[3 * i]; y = v[3 * i + 1]; r = v[3 * i + 2]
        for which, slack in ((0, x - r), (1, 1 - x - r), (2, y - r), (3, 1 - y - r)):
            t = 'eq' if slack < active_tol else 'ineq'
            cons.append({'type': t,
                         'fun': (lambda v, i=i, which=which: _wall_fun(v, i, which)),
                         'jac': (lambda v, i=i, which=which: _wall_jacs(v, i, which))})
    for i in range(n):
        for j in range(i + 1, n):
            slack = _pair_cons(v, i, j)
            if slack < active_tol:
                cons.append({'type': 'eq',
                             'fun': (lambda v, i=i, j=j: _pair_cons(v, i, j)),
                             'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
            else:
                cons.append({'type': 'ineq',
                             'fun': (lambda v, i=i, j=j: _pair_cons(v, i, j)),
                             'jac': (lambda v, i=i, j=j: _pair_jac(v, i, j))})
    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))
    try:
        res = minimize(_obj, v, jac=_obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol, 'disp': False})
        if res.x is not None and np.all(np.isfinite(res.x)):
            return res.x.reshape(n, 3).copy()
    except Exception:
        pass
    return arr.copy()


def _wall_fun(v, i, which):
    x = v[3 * i]; y = v[3 * i + 1]; r = v[3 * i + 2]
    if which == 0:
        return x - r
    if which == 1:
        return 1.0 - x - r
    if which == 2:
        return y - r
    return 1.0 - y - r


def _polish(centers, r):
    n = centers.shape[0]
    r = r.copy()
    for _ in range(200):
        violated = False
        for i in range(n):
            x, y = centers[i, 0], centers[i, 1]
            for dist in (x, 1.0 - x, y, 1.0 - y):
                if r[i] > dist:
                    r[i] = dist
                    violated = True
        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i, 0] - centers[j, 0]
                dy = centers[i, 1] - centers[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if s > d:
                    corr = (s - d) / 2.0 + 1e-15
                    r[i] -= corr
                    r[j] -= corr
                    violated = True
        if not violated:
            break
    return r


def _sample_centers(rng, n):
    kind = rng.integers(0, 3)
    if kind == 0:
        pts = []
        for j in range(5):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
        pts.append((0.5, 0.5))
        pts = np.array(pts)
        sigma = rng.choice([0.02, 0.05, 0.1])
        pts = pts + rng.normal(0.0, sigma, size=pts.shape)
        return np.clip(pts, 0.0, 1.0)
    elif kind == 1:
        dmin = rng.uniform(0.13, 0.20)
        pts = []
        tries = 0
        while len(pts) < n and tries < 5000:
            tries += 1
            p = rng.uniform(0.0, 1.0, size=2)
            if not pts:
                pts.append(p)
                continue
            arr = np.array(pts)
            dd = np.hypot(arr[:, 0] - p[0], arr[:, 1] - p[1])
            if np.all(dd >= dmin):
                pts.append(p)
        pts = np.array(pts)
        if len(pts) < n:
            extra = rng.uniform(0.0, 1.0, size=(n - len(pts), 2))
            pts = np.vstack([pts, extra])
        return pts[:n]
    else:
        return rng.uniform(0.0, 1.0, size=(n, 2))


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26

    # --- start from provided solution ---
    if start is not None:
        arr = np.asarray(start, dtype=float).copy()
        if arr.shape != (n, 3):
            arr = None
    else:
        arr = None

    if arr is not None:
        arr = _feasible(arr)
        best = _slsqp(arr, 2000, active_tol=1e-6, ftol=1e-14)
        if np.sum(best[:, 2]) < np.sum(arr[:, 2]):
            best = arr
    else:
        # fallback grid
        pts = []
        for j in range(5):
            for i in range(5):
                pts.append(((i + 0.5) / 5.0, (j + 0.5) / 5.0))
        pts.append((0.5, 0.5))
        arr = np.array([[x, y, 0.09] for x, y in pts])
        arr = _feasible(arr)
        best = _slsqp(arr, 2000)

    best_score = float(np.sum(best[:, 2]))
    rng = np.random.default_rng(2024)

    # --- Phase A: penalty L-BFGS-B multi-start, keep pool ---
    pool = [(best_score, best.copy())]
    # also include LP-refined versions of best
    while time.process_time() - t0 < 0.55 * budget_seconds:
        centers = _sample_centers(rng, n)
        try:
            radii = _lp_radii(centers)
        except Exception:
            continue
        v0 = np.column_stack([centers, radii]).reshape(-1)
        cand = _penalty_solve(v0, n, iters=400)
        s = float(np.sum(cand[:, 2]))
        pool.append((s, cand))
        if len(pool) > 30:
            pool.sort(key=lambda t: -t[0])
            pool = pool[:20]

    # --- Phase B: refine top candidates with SLSQP ---
    pool.sort(key=lambda t: -t[0])
    for s, cand in pool[:6]:
        if time.process_time() - t0 >= 0.78 * budget_seconds:
            break
        cand = _feasible(cand)
        res = _slsqp(cand, 1500, active_tol=1e-6, ftol=1e-14)
        sc = float(np.sum(res[:, 2]))
        if sc > best_score:
            best = res
            best_score = sc

    # --- Phase C: basin hopping on best ---
    it = 0
    while time.process_time() - t0 < 0.90 * budget_seconds:
        it += 1
        sigma_c = 0.03 if (it % 4 == 0) else 0.012
        cand = best.copy()
        cand[:, 0] += rng.normal(0.0, sigma_c, size=n)
        cand[:, 1] += rng.normal(0.0, sigma_c, size=n)
        cand[:, 2] += rng.normal(0.0, 0.003, size=n)
        cand[:, 2] = np.maximum(cand[:, 2], 1e-6)
        for i in range(n):
            r = cand[i, 2]
            cand[i, 0] = min(max(cand[i, 0], r), 1.0 - r)
            cand[i, 1] = min(max(cand[i, 1], r), 1.0 - r)
        cand = _feasible(cand)
        res = _slsqp(cand, 400, active_tol=1e-6, ftol=1e-13)
        sc = float(np.sum(res[:, 2]))
        if sc > best_score + 1e-12:
            best = res
            best_score = sc

    # --- final LP radii + polish ---
    centers = best[:, :2].copy()
    r = _lp_radii(centers)
    r = _polish(centers, r)
    r = np.maximum(r, 1e-9)
    out = np.column_stack([centers, r])
    # safety: shrink radii slightly for exact feasibility
    out[:, 2] -= 1e-12
    out[:, 2] = np.maximum(out[:, 2], 1e-9)
    return out
